namespace
{
	template <class T, class... A>
	inline T* shard_make_new(A&&... args)
	{
		if constexpr (std::is_constructible_v<T, A...>)
		{
			return new T(std::forward<A>(args)...);
		}
		else
		{
			return nullptr;
		}
	}

	template <class T, class V>
	inline T* shard_box_value(V&& value)
	{
		if constexpr (std::is_constructible_v<T, V&&>)
		{
			return new T(std::forward<V>(value));
		}
		else
		{
			return nullptr;
		}
	}

	template <class T>
	inline void shard_release(T* value)
	{
		if constexpr (std::is_destructible_v<T>)
		{
			delete value;
		}
	}
}

